FILES={"seed_companion_v137.py": "import json, os, signal, subprocess, sys, time, shlex\nfrom pathlib import Path\nfrom datetime import datetime\n\nVERSION = \"v137.0.0\"\nPID = Path(\"seed_companion_v137.pid\")\nSTATE = Path(\"seed_companion_v137_state.json\")\nEVENTS = Path(\"seed_companion_v137_events.jsonl\")\nINBOX = Path(\"seed_companion_v137_inbox.jsonl\")\nLOG = Path(\"seed_companion_v137.log\")\nSETTINGS = Path(\"seed_companion_v137_settings.json\")\n\nDEFAULT_SETTINGS = {\n    \"version\": VERSION,\n    \"mode\": \"safe_presence\",\n    \"loop_interval_seconds\": 2,\n    \"cooldown_seconds\": 8,\n    \"auto_start_services\": True,\n    \"start_ui\": False,\n    \"start_autopilot\": True,\n    \"start_voice_runtime\": True,\n    \"start_proactive\": True,\n    \"start_dashboard_avatar\": True,\n    \"audio_wake_enabled\": False,\n    \"audio_probe_seconds\": 3,\n    \"wake_phrases\": [\"wake up\", \"hey seed\", \"seed\"],\n    \"ignore_phrases\": [\"pumpkin seed\", \"seed recipe\"],\n    \"speak_default\": False,\n    \"max_events\": 1200,\n    \"note\": \"v137 defaults to safe presence. Audio wake can be enabled after explicit testing.\"\n}\n\ndef now():\n    return datetime.now().isoformat(timespec=\"seconds\")\n\ndef load_json(path, default):\n    if Path(path).exists():\n        try:\n            obj = json.loads(Path(path).read_text(errors=\"ignore\"))\n            if isinstance(obj, dict):\n                base = default.copy()\n                base.update(obj)\n                base[\"version\"] = VERSION\n                return base\n        except Exception:\n            pass\n    Path(path).write_text(json.dumps(default, indent=4, ensure_ascii=False))\n    return default.copy()\n\ndef settings():\n    return load_json(SETTINGS, DEFAULT_SETTINGS)\n\ndef save_settings(s):\n    s[\"version\"] = VERSION\n    SETTINGS.write_text(json.dumps(s, indent=4, ensure_ascii=False))\n    return s\n\ndef write_state(obj):\n    obj[\"updated_at\"] = now()\n    obj[\"version\"] = VERSION\n    STATE.write_text(json.dumps(obj, indent=4, ensure_ascii=False))\n    return obj\n\ndef event(row):\n    row.setdefault(\"created_at\", now())\n    row.setdefault(\"version\", VERSION)\n    with EVENTS.open(\"a\") as f:\n        f.write(json.dumps(row, ensure_ascii=False) + \"\\n\")\n    trim_events()\n    return row\n\ndef trim_events():\n    if not EVENTS.exists():\n        return\n    try:\n        s = settings()\n        max_events = int(s.get(\"max_events\", 1200))\n        lines = EVENTS.read_text(errors=\"ignore\").splitlines()\n        if len(lines) > max_events:\n            EVENTS.write_text(\"\\n\".join(lines[-max_events:]) + \"\\n\")\n    except Exception:\n        pass\n\ndef alive(pid):\n    try:\n        os.kill(int(pid), 0)\n        return True\n    except Exception:\n        return False\n\ndef run(cmd, timeout=90):\n    try:\n        p = subprocess.run(cmd, capture_output=True, text=True, timeout=timeout)\n        out = (p.stdout or \"\").strip()\n        data = None\n        if out:\n            try:\n                data = json.loads(out)\n            except Exception:\n                data = {\"raw\": out}\n        return {\"ok\": p.returncode == 0, \"returncode\": p.returncode, \"cmd\": cmd, \"stdout\": out[-4000:], \"stderr\": (p.stderr or \"\")[-2000:], \"data\": data}\n    except subprocess.TimeoutExpired:\n        return {\"ok\": False, \"cmd\": cmd, \"error\": \"timeout\"}\n    except Exception as e:\n        return {\"ok\": False, \"cmd\": cmd, \"error\": str(e)}\n\ndef py(script, *args):\n    return [sys.executable, script, *args]\n\ndef service_status():\n    rows = {}\n    commands = {\n        \"voice_runtime\": py(\"seed_voice_runtime_v136.py\", \"status\"),\n        \"approval_autopilot\": py(\"seed_approval_autopilot_v13623.py\", \"status\"),\n        \"effective_hygiene\": py(\"seed_hygiene_status_v13623.py\", \"--json\"),\n        \"dashboard\": py(\"seed_dashboard_v106.py\", \"status\"),\n        \"avatar\": py(\"seed_avatar2_v129.py\", \"status\"),\n        \"proactive\": py(\"seed_proactive_rhythm_v108.py\", \"status\"),\n    }\n    for name, cmd in commands.items():\n        if Path(cmd[1]).exists():\n            rows[name] = run(cmd, timeout=30)\n        else:\n            rows[name] = {\"ok\": False, \"missing\": cmd[1]}\n    return rows\n\ndef start_services():\n    s = settings()\n    actions = []\n    if not s.get(\"auto_start_services\", True):\n        return {\"ok\": True, \"skipped\": True, \"actions\": actions}\n    if s.get(\"start_dashboard_avatar\", True):\n        if Path(\"seed_dashboard_v106.py\").exists():\n            actions.append({\"service\": \"dashboard\", \"result\": run(py(\"seed_dashboard_v106.py\", \"start\"))})\n        if Path(\"seed_avatar2_v129.py\").exists():\n            actions.append({\"service\": \"avatar\", \"result\": run(py(\"seed_avatar2_v129.py\", \"start\"))})\n    if s.get(\"start_proactive\", True) and Path(\"seed_proactive_rhythm_v108.py\").exists():\n        actions.append({\"service\": \"proactive\", \"result\": run(py(\"seed_proactive_rhythm_v108.py\", \"start\"))})\n    if s.get(\"start_voice_runtime\", True) and Path(\"seed_voice_runtime_v136.py\").exists():\n        actions.append({\"service\": \"voice_runtime\", \"result\": run(py(\"seed_voice_runtime_v136.py\", \"start\", \"--no-speak\"))})\n    if s.get(\"start_autopilot\", True) and Path(\"seed_approval_autopilot_v13623.py\").exists():\n        actions.append({\"service\": \"approval_autopilot\", \"result\": run(py(\"seed_approval_autopilot_v13623.py\", \"start\"))})\n    event({\"event\": \"start_services\", \"actions\": actions})\n    return {\"ok\": True, \"actions\": actions}\n\ndef stop_services():\n    actions = []\n    # Stop companion-adjacent services, but keep dashboard/avatar unless user uses stop-all.\n    if Path(\"seed_approval_autopilot_v13623.py\").exists():\n        actions.append({\"service\": \"approval_autopilot\", \"result\": run(py(\"seed_approval_autopilot_v13623.py\", \"stop\"))})\n    if Path(\"seed_voice_runtime_v136.py\").exists():\n        actions.append({\"service\": \"voice_runtime\", \"result\": run(py(\"seed_voice_runtime_v136.py\", \"stop\"))})\n    event({\"event\": \"stop_services\", \"actions\": actions})\n    return {\"ok\": True, \"actions\": actions}\n\ndef stop_all_services():\n    actions = []\n    for script, name in [\n        (\"seed_approval_autopilot_v13623.py\", \"approval_autopilot\"),\n        (\"seed_voice_runtime_v136.py\", \"voice_runtime\"),\n        (\"seed_proactive_rhythm_v108.py\", \"proactive\"),\n        (\"seed_avatar2_v129.py\", \"avatar\"),\n        (\"seed_dashboard_v106.py\", \"dashboard\")\n    ]:\n        if Path(script).exists():\n            actions.append({\"service\": name, \"result\": run(py(script, \"stop\"))})\n    event({\"event\": \"stop_all_services\", \"actions\": actions})\n    return {\"ok\": True, \"actions\": actions}\n\ndef enqueue(text, source=\"manual\"):\n    row = {\"created_at\": now(), \"version\": VERSION, \"source\": source, \"text\": text, \"processed\": False}\n    with INBOX.open(\"a\") as f:\n        f.write(json.dumps(row, ensure_ascii=False) + \"\\n\")\n    event({\"event\": \"enqueue\", \"text\": text, \"source\": source})\n    return {\"ok\": True, \"queued\": row}\n\ndef read_inbox():\n    rows = []\n    if not INBOX.exists():\n        return rows\n    for line in INBOX.read_text(errors=\"ignore\").splitlines():\n        if not line.strip():\n            continue\n        try:\n            rows.append(json.loads(line))\n        except Exception:\n            rows.append({\"created_at\": now(), \"text\": line, \"processed\": False, \"unparsed\": True})\n    return rows\n\ndef write_inbox(rows):\n    INBOX.write_text(\"\\n\".join(json.dumps(r, ensure_ascii=False) for r in rows) + (\"\\n\" if rows else \"\"))\n\ndef wake_match(text):\n    s = settings()\n    t = (text or \"\").lower().strip()\n    for bad in s.get(\"ignore_phrases\", []):\n        if bad in t:\n            return {\"ok\": True, \"matched\": False, \"reason\": \"ignore_phrase\", \"phrase\": bad, \"rest\": \"\"}\n    for phrase in s.get(\"wake_phrases\", []):\n        p = phrase.lower()\n        if t == p:\n            return {\"ok\": True, \"matched\": True, \"phrase\": phrase, \"rest\": \"\"}\n        if t.startswith(p + \" \"):\n            return {\"ok\": True, \"matched\": True, \"phrase\": phrase, \"rest\": text[len(phrase):].strip()}\n    # If v132 matcher exists, use it as a second opinion.\n    try:\n        import seed_real_wake_v132 as wake\n        if hasattr(wake, \"text_match\"):\n            m = wake.text_match(text)\n            if isinstance(m, dict) and m.get(\"matched\"):\n                return {\"ok\": True, \"matched\": True, \"phrase\": m.get(\"phrase\"), \"rest\": m.get(\"rest\",\"\"), \"engine\": \"seed_real_wake_v132\"}\n    except Exception:\n        pass\n    return {\"ok\": True, \"matched\": False, \"reason\": \"no_match\", \"rest\": \"\"}\n\ndef run_text_runtime(text):\n    args = [\"wake-text\", \"wake up \" + text if not text.lower().startswith((\"wake up\", \"hey seed\", \"seed\")) else text]\n    if not settings().get(\"speak_default\", False):\n        args.append(\"--no-speak\")\n    if Path(\"seed_voice_runtime_v136.py\").exists():\n        return run(py(\"seed_voice_runtime_v136.py\", *args), timeout=180)\n    return {\"ok\": False, \"error\": \"seed_voice_runtime_v136.py missing\"}\n\ndef run_voice_once():\n    # Tries the v136 voice runtime CLI first; fallback to v133 listen.\n    if Path(\"seed_voice_runtime_v136.py\").exists():\n        r = run(py(\"seed_voice_runtime_v136.py\", \"voice-once\", \"--no-speak\"), timeout=180)\n        if r.get(\"ok\"):\n            return r\n    if Path(\"seed_voice_conversation_v133.py\").exists():\n        return run(py(\"seed_voice_conversation_v133.py\", \"listen\", \"--no-speak\"), timeout=180)\n    return {\"ok\": False, \"error\": \"no voice once command available\"}\n\ndef extract_transcript(result):\n    data = result.get(\"data\") if isinstance(result, dict) else result\n    if not isinstance(data, dict):\n        return None\n    # Common shapes from previous modules.\n    paths = [\n        [\"transcript\"],\n        [\"text\"],\n        [\"listen\", \"transcript\", \"text\"],\n        [\"result\", \"listen\", \"transcript\", \"text\"],\n        [\"session\", \"input\"],\n        [\"result\", \"session\", \"input\"],\n        [\"event\", \"result\", \"session\", \"input\"],\n    ]\n    for path in paths:\n        cur = data\n        for k in path:\n            if isinstance(cur, dict) and k in cur:\n                cur = cur[k]\n            else:\n                cur = None; break\n        if isinstance(cur, str) and cur.strip():\n            return cur.strip()\n    # Search recursively.\n    return find_textish(data)\n\ndef find_textish(obj):\n    if isinstance(obj, dict):\n        for key in [\"transcript\", \"text\", \"input\", \"normalized_text\"]:\n            v = obj.get(key)\n            if isinstance(v, str) and len(v.strip()) >= 2:\n                return v.strip()\n        for v in obj.values():\n            r = find_textish(v)\n            if r:\n                return r\n    elif isinstance(obj, list):\n        for x in obj:\n            r = find_textish(x)\n            if r:\n                return r\n    return None\n\ndef process_text(text, source=\"inbox\"):\n    wm = wake_match(text)\n    row = {\"event\": \"text_received\", \"source\": source, \"text\": text, \"wake\": wm}\n    if not wm.get(\"matched\"):\n        row[\"handled\"] = False\n        event(row)\n        return {\"ok\": True, \"handled\": False, \"wake\": wm}\n    rest = wm.get(\"rest\") or \"status\"\n    runtime = run_text_runtime(rest)\n    row[\"handled\"] = True\n    row[\"runtime\"] = runtime\n    event(row)\n    return {\"ok\": True, \"handled\": True, \"wake\": wm, \"runtime\": runtime}\n\ndef process_inbox():\n    rows = read_inbox()\n    changed = False\n    results = []\n    for r in rows:\n        if r.get(\"processed\"):\n            continue\n        res = process_text(r.get(\"text\",\"\"), source=r.get(\"source\",\"inbox\"))\n        r[\"processed\"] = True\n        r[\"processed_at\"] = now()\n        r[\"result\"] = res\n        changed = True\n        results.append(res)\n    if changed:\n        write_inbox(rows)\n    return {\"ok\": True, \"processed\": len(results), \"results\": results}\n\ndef audio_probe():\n    s = settings()\n    if not s.get(\"audio_wake_enabled\", False):\n        return {\"ok\": True, \"skipped\": True, \"reason\": \"audio_wake_disabled\"}\n    # Conservative: listen short snippet and only run full voice once if wake word detected.\n    if Path(\"seed_voice_input_v131.py\").exists():\n        r = run(py(\"seed_voice_input_v131.py\", \"listen-once\", str(s.get(\"audio_probe_seconds\", 3))), timeout=180)\n    elif Path(\"seed_voice_conversation_v133.py\").exists():\n        r = run(py(\"seed_voice_conversation_v133.py\", \"listen\", \"--no-speak\"), timeout=180)\n    else:\n        return {\"ok\": False, \"error\": \"no audio input module\"}\n    transcript = extract_transcript(r)\n    wm = wake_match(transcript or \"\")\n    out = {\"ok\": True, \"probe\": r, \"transcript\": transcript, \"wake\": wm, \"handled\": False}\n    if transcript and wm.get(\"matched\"):\n        rest = wm.get(\"rest\")\n        if rest:\n            out[\"runtime\"] = run_text_runtime(rest)\n        else:\n            out[\"runtime\"] = run_voice_once()\n        out[\"handled\"] = True\n    event({\"event\": \"audio_probe\", \"transcript\": transcript, \"wake\": wm, \"handled\": out.get(\"handled\")})\n    return out\n\ndef loop_tick():\n    results = {\"created_at\": now(), \"version\": VERSION, \"inbox\": process_inbox(), \"audio\": audio_probe()}\n    return results\n\ndef daemon():\n    s = settings()\n    start_services()\n    write_state({\"alive\": True, \"pid\": os.getpid(), \"mode\": s.get(\"mode\"), \"started_at\": now(), \"last_tick\": None})\n    event({\"event\": \"daemon_started\", \"pid\": os.getpid(), \"settings\": s})\n    last_handled = 0\n    while True:\n        s = settings()\n        try:\n            tick = loop_tick()\n            write_state({\"alive\": True, \"pid\": os.getpid(), \"mode\": s.get(\"mode\"), \"last_tick\": tick, \"heartbeat_at\": now()})\n        except Exception as e:\n            event({\"event\": \"daemon_error\", \"error\": str(e)})\n            write_state({\"alive\": True, \"pid\": os.getpid(), \"mode\": s.get(\"mode\"), \"error\": str(e), \"heartbeat_at\": now()})\n        time.sleep(float(s.get(\"loop_interval_seconds\", 2)))\n\ndef start(audio=False, ui=False):\n    s = settings()\n    if audio:\n        s[\"audio_wake_enabled\"] = True\n    if ui:\n        s[\"start_ui\"] = True\n    save_settings(s)\n    if PID.exists():\n        try:\n            pid = int(PID.read_text().strip())\n            if alive(pid):\n                return {\"ok\": True, \"already_running\": True, \"pid\": pid, \"settings\": s}\n        except Exception:\n            pass\n    p = subprocess.Popen([sys.executable, \"seed_companion_v137.py\", \"daemon\"], stdout=LOG.open(\"a\"), stderr=LOG.open(\"a\"))\n    PID.write_text(str(p.pid))\n    time.sleep(0.7)\n    return {\"ok\": True, \"pid\": p.pid, \"settings\": s}\n\ndef stop(stop_services_flag=False):\n    pid = None; stopped = False\n    if PID.exists():\n        try:\n            pid = int(PID.read_text().strip())\n            if alive(pid):\n                os.kill(pid, signal.SIGTERM)\n                stopped = True\n            PID.unlink(missing_ok=True)\n        except Exception:\n            pass\n    write_state({\"alive\": False, \"pid\": None, \"stopped_at\": now()})\n    event({\"event\": \"daemon_stopped\", \"pid\": pid, \"stopped\": stopped})\n    service_result = None\n    if stop_services_flag:\n        service_result = stop_services()\n    return {\"ok\": True, \"stopped\": stopped, \"pid\": pid, \"services\": service_result}\n\ndef status():\n    pid = None; al = False\n    if PID.exists():\n        try:\n            pid = int(PID.read_text().strip())\n            al = alive(pid)\n        except Exception:\n            pass\n    state = {}\n    if STATE.exists():\n        try:\n            state = json.loads(STATE.read_text(errors=\"ignore\"))\n        except Exception:\n            state = {}\n    recent = []\n    if EVENTS.exists():\n        for line in EVENTS.read_text(errors=\"ignore\").splitlines()[-20:]:\n            try:\n                recent.append(json.loads(line))\n            except Exception:\n                pass\n    return {\n        \"created_at\": now(),\n        \"version\": VERSION,\n        \"ok\": True,\n        \"alive\": al,\n        \"pid\": pid,\n        \"settings\": settings(),\n        \"state\": state,\n        \"services\": service_status(),\n        \"inbox_pending\": len([r for r in read_inbox() if not r.get(\"processed\")]),\n        \"recent_events\": recent\n    }\n\ndef configure(key, value):\n    s = settings()\n    if value.lower() in {\"true\",\"yes\",\"1\",\"on\"}:\n        v = True\n    elif value.lower() in {\"false\",\"no\",\"0\",\"off\"}:\n        v = False\n    else:\n        try:\n            v = int(value)\n        except Exception:\n            v = value\n    s[key] = v\n    save_settings(s)\n    return {\"ok\": True, \"settings\": s}\n\ndef test():\n    start_res = start_services()\n    q = enqueue(\"wake up status\", source=\"v137_test\")\n    proc = process_inbox()\n    wm_good = wake_match(\"wake up status\")\n    wm_bad = wake_match(\"pumpkin seed recipe\")\n    return {\"ok\": True, \"start_services\": start_res, \"enqueue\": q, \"process\": proc, \"wake_good\": wm_good, \"wake_bad\": wm_bad, \"status\": status()}\n\nif __name__ == \"__main__\":\n    args = sys.argv[1:]\n    cmd = args[0] if args else \"status\"\n    if cmd == \"daemon\":\n        daemon()\n    elif cmd == \"start\":\n        print(json.dumps(start(audio=\"--audio\" in args, ui=\"--ui\" in args), indent=4, ensure_ascii=False))\n    elif cmd == \"stop\":\n        print(json.dumps(stop(stop_services_flag=\"--services\" in args or \"--all\" in args), indent=4, ensure_ascii=False))\n    elif cmd == \"stop-all\":\n        print(json.dumps({\"companion\": stop(False), \"services\": stop_all_services()}, indent=4, ensure_ascii=False))\n    elif cmd == \"enqueue\":\n        print(json.dumps(enqueue(\" \".join(args[1:]) or \"wake up status\"), indent=4, ensure_ascii=False))\n    elif cmd == \"process\":\n        print(json.dumps(process_inbox(), indent=4, ensure_ascii=False))\n    elif cmd == \"tick\":\n        print(json.dumps(loop_tick(), indent=4, ensure_ascii=False))\n    elif cmd == \"audio-on\":\n        print(json.dumps(configure(\"audio_wake_enabled\", \"true\"), indent=4, ensure_ascii=False))\n    elif cmd == \"audio-off\":\n        print(json.dumps(configure(\"audio_wake_enabled\", \"false\"), indent=4, ensure_ascii=False))\n    elif cmd == \"set\" and len(args) >= 3:\n        print(json.dumps(configure(args[1], args[2]), indent=4, ensure_ascii=False))\n    elif cmd == \"test\":\n        print(json.dumps(test(), indent=4, ensure_ascii=False))\n    else:\n        print(json.dumps(status(), indent=4, ensure_ascii=False))\n", "seed_companion_panel_v137.py": "import json, os, signal, subprocess, sys\nfrom http.server import BaseHTTPRequestHandler, HTTPServer\nfrom pathlib import Path\nfrom urllib.parse import urlparse, parse_qs\nfrom datetime import datetime\n\nPID = Path(\"seed_companion_panel_v137.pid\")\nLOG = Path(\"seed_companion_panel_v137.log\")\nPORT = 8821\n\nHTML = \"\"\"<!doctype html><html><head><meta charset='utf-8'><title>Seed Companion v137</title><meta name='viewport' content='width=device-width,initial-scale=1'><style>\nbody{margin:0;background:radial-gradient(circle at 10% 0%,rgba(255,138,35,.22),transparent 35%),#050505;color:#f4f4f2;font-family:-apple-system,BlinkMacSystemFont,Segoe UI,sans-serif}.wrap{max-width:1200px;margin:0 auto;padding:28px}.hero,.card{background:#111318;border:1px solid #2a2d33;border-radius:24px;padding:22px;margin:14px 0}.title{font-size:44px;font-weight:900;letter-spacing:-.055em}.muted{color:#a3a7ad}.grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(300px,1fr));gap:14px}.big{font-size:42px;font-weight:900;color:#72f59c}.bad{color:#ff6868}button{background:#ff8a23;color:#111;border:0;border-radius:13px;padding:12px 15px;font-weight:850;margin:5px;cursor:pointer}.secondary{background:#1a1d22;color:#f4f4f2;border:1px solid #2a2d33}input{background:#08090b;color:#f4f4f2;border:1px solid #2a2d33;border-radius:12px;padding:12px;width:65%}pre{white-space:pre-wrap;word-break:break-word;background:#08090b;border:1px solid #24272e;border-radius:14px;padding:12px;max-height:540px;overflow:auto}</style></head><body><div class='wrap'><div class='hero'><div class='muted'>Local Companion OS</div><div class='title'>Seed Companion v137</div><p class='muted'>Presence runtime: dashboard + avatar + proactive + voice + autonomy + wake loop.</p><button onclick='api(\"start\")'>Start Companion</button><button onclick='api(\"start-audio\")'>Start + Audio Wake</button><button class='secondary' onclick='api(\"stop\")'>Stop Companion</button><button class='secondary' onclick='api(\"audio-off\")'>Audio Off</button></div><div class='card'><input id='msg' value='wake up status'><button onclick='api(\"enqueue?text=\"+encodeURIComponent(msg.value))'>Send Wake Text</button><button class='secondary' onclick='api(\"tick\")'>Tick</button></div><div class='grid'><div class='card'><div class='muted'>Companion</div><div id='alive' class='big'>—</div><div id='pid' class='muted'></div></div><div class='card'><div class='muted'>Hygiene</div><pre id='hygiene'>loading</pre></div><div class='card'><div class='muted'>Services</div><pre id='services'>loading</pre></div></div><div class='card'><h3>Recent Events</h3><pre id='events'>loading</pre></div><div class='card'><h3>Raw Status</h3><pre id='raw'>loading</pre></div></div><script>\nasync function api(path){let j=await(await fetch('/api/'+path)).json();raw.textContent=JSON.stringify(j,null,2);await refresh();alert(JSON.stringify(j,null,2).slice(0,1000))}\nasync function refresh(){let j=await(await fetch('/api/status?'+Date.now())).json();raw.textContent=JSON.stringify(j,null,2);alive.textContent=j.alive?'ALIVE':'STOPPED';alive.className=j.alive?'big':'big bad';pid.textContent='pid '+(j.pid||'—');services.textContent=JSON.stringify(j.services_summary||{},null,2);hygiene.textContent=JSON.stringify(j.hygiene_summary||{},null,2);events.textContent=JSON.stringify(j.recent_events||[],null,2)}\nrefresh();setInterval(refresh,3000)\n</script></body></html>\"\"\"\n\ndef now():\n    return datetime.now().isoformat(timespec=\"seconds\")\n\ndef alive(pid):\n    try:\n        os.kill(int(pid),0); return True\n    except Exception: return False\n\nclass H(BaseHTTPRequestHandler):\n    def send_json(self,obj):\n        b=json.dumps(obj,ensure_ascii=False).encode()\n        self.send_response(200); self.send_header(\"Content-Type\",\"application/json\"); self.end_headers(); self.wfile.write(b)\n    def do_GET(self):\n        p=urlparse(self.path); q=parse_qs(p.query)\n        try:\n            import seed_companion_v137 as c\n            if p.path == \"/api/status\":\n                st=c.status()\n                st[\"services_summary\"]=summarize_services(st.get(\"services\",{}))\n                st[\"hygiene_summary\"]=extract_hygiene(st.get(\"services\",{}))\n                self.send_json(st)\n            elif p.path == \"/api/start\":\n                self.send_json(c.start())\n            elif p.path == \"/api/start-audio\":\n                self.send_json(c.start(audio=True))\n            elif p.path == \"/api/stop\":\n                self.send_json(c.stop())\n            elif p.path == \"/api/audio-off\":\n                self.send_json(c.configure(\"audio_wake_enabled\",\"false\"))\n            elif p.path == \"/api/tick\":\n                self.send_json(c.loop_tick())\n            elif p.path == \"/api/enqueue\":\n                self.send_json(c.enqueue((q.get(\"text\") or [\"wake up status\"])[0], source=\"panel\"))\n            else:\n                b=HTML.encode(); self.send_response(200); self.send_header(\"Content-Type\",\"text/html\"); self.end_headers(); self.wfile.write(b)\n        except Exception as e:\n            self.send_json({\"ok\":False,\"error\":str(e)})\n    def log_message(self,*a): return\n\ndef summarize_services(services):\n    out={}\n    for k,v in services.items():\n        data=v.get(\"data\") if isinstance(v,dict) else None\n        if isinstance(data,dict):\n            out[k]={\"ok\":v.get(\"ok\"),\"alive\":data.get(\"alive\"),\"pid\":data.get(\"pid\"),\"url\":data.get(\"url\")}\n        else:\n            out[k]={\"ok\":v.get(\"ok\") if isinstance(v,dict) else False}\n    return out\n\ndef extract_hygiene(services):\n    h=services.get(\"effective_hygiene\",{}) if isinstance(services,dict) else {}\n    data=h.get(\"data\") if isinstance(h,dict) else None\n    if isinstance(data,dict):\n        hv=data.get(\"hygiene_v13623\") or data.get(\"hygiene\") or {}\n        return {\"score\":hv.get(\"score\"),\"grade\":hv.get(\"grade\"),\"reasons\":hv.get(\"reasons\"),\"approval_effective\":(data.get(\"approval_v13623\") or {}).get(\"effective_pending_count\")}\n    return {}\n\ndef serve():\n    HTTPServer((\"127.0.0.1\", PORT), H).serve_forever()\n\ndef start():\n    if PID.exists():\n        try:\n            pid=int(PID.read_text().strip())\n            if alive(pid):\n                subprocess.Popen([\"open\",f\"http://127.0.0.1:{PORT}/\"])\n                return {\"ok\":True,\"already_running\":True,\"pid\":pid,\"url\":f\"http://127.0.0.1:{PORT}/\"}\n        except Exception: pass\n    p=subprocess.Popen([sys.executable,\"seed_companion_panel_v137.py\",\"serve\"],stdout=LOG.open(\"a\"),stderr=LOG.open(\"a\"))\n    PID.write_text(str(p.pid))\n    subprocess.Popen([\"open\",f\"http://127.0.0.1:{PORT}/\"])\n    return {\"ok\":True,\"pid\":p.pid,\"url\":f\"http://127.0.0.1:{PORT}/\"}\n\ndef stop():\n    pid=None; stopped=False\n    if PID.exists():\n        try:\n            pid=int(PID.read_text().strip())\n            if alive(pid): os.kill(pid,signal.SIGTERM); stopped=True\n            PID.unlink(missing_ok=True)\n        except Exception: pass\n    return {\"ok\":True,\"stopped\":stopped,\"pid\":pid}\n\ndef status():\n    pid=None; al=False\n    if PID.exists():\n        try: pid=int(PID.read_text().strip()); al=alive(pid)\n        except Exception: pass\n    return {\"created_at\":now(),\"version\":\"v137.0.0\",\"ok\":True,\"alive\":al,\"pid\":pid,\"url\":f\"http://127.0.0.1:{PORT}/\"}\n\nif __name__==\"__main__\":\n    a=sys.argv[1] if len(sys.argv)>1 else \"status\"\n    if a==\"serve\": serve()\n    elif a==\"start\": print(json.dumps(start(),indent=4,ensure_ascii=False))\n    elif a==\"stop\": print(json.dumps(stop(),indent=4,ensure_ascii=False))\n    else: print(json.dumps(status(),indent=4,ensure_ascii=False))\n", "seed_v137_companion_gate.py": "import json, subprocess, sys\nfrom pathlib import Path\nfrom datetime import datetime\n\nMODULES=[\"seed_companion_v137.py\",\"seed_companion_panel_v137.py\",\"seed_v137_companion_gate.py\"]\n\ndef now():\n    return datetime.now().isoformat(timespec=\"seconds\")\n\ndef comp(m):\n    p=subprocess.run([sys.executable,\"-m\",\"py_compile\",m],capture_output=True,text=True,timeout=30)\n    return {\"module\":m,\"ok\":p.returncode==0,\"stderr\":p.stderr[-1000:]}\n\ndef run_gate():\n    checks=[comp(m) for m in MODULES]\n    modules_ok=all(c[\"ok\"] for c in checks)\n    details={}\n    try:\n        import seed_companion_v137 as c\n        test=c.test()\n        st=c.status()\n        details[\"companion_test\"]=test\n        details[\"companion_status\"]=st\n        companion_ok=test.get(\"ok\") is True and test.get(\"wake_good\",{}).get(\"matched\") is True and test.get(\"wake_bad\",{}).get(\"matched\") is False\n    except Exception as e:\n        companion_ok=False; details[\"companion_error\"]=str(e)\n    try:\n        import seed_companion_panel_v137 as p\n        ps=p.status()\n        details[\"panel_status\"]=ps\n        panel_ok=ps.get(\"ok\") is True\n    except Exception as e:\n        panel_ok=False; details[\"panel_error\"]=str(e)\n    try:\n        if Path(\"seed_hygiene_status_v13623.py\").exists():\n            p=subprocess.run([sys.executable,\"seed_hygiene_status_v13623.py\",\"--json\"],capture_output=True,text=True,timeout=60)\n            data=json.loads(p.stdout) if p.stdout.strip() else {}\n            details[\"hygiene\"]=data.get(\"hygiene_v13623\") or data.get(\"hygiene\")\n            hygiene_ok=p.returncode==0\n        else:\n            hygiene_ok=False; details[\"hygiene_error\"]=\"missing seed_hygiene_status_v13623.py\"\n    except Exception as e:\n        hygiene_ok=False; details[\"hygiene_error\"]=str(e)\n    report={\n        \"created_at\":now(),\n        \"version\":\"v137.0.0\",\n        \"ready\":modules_ok and companion_ok and panel_ok and hygiene_ok,\n        \"modules_ok\":modules_ok,\n        \"companion_ok\":companion_ok,\n        \"panel_ok\":panel_ok,\n        \"hygiene_ok\":hygiene_ok,\n        \"checks\":checks,\n        \"details\":details\n    }\n    Path(\"seed_v137_companion_gate_report.json\").write_text(json.dumps(report,indent=4,ensure_ascii=False))\n    return report\n\ndef show():\n    r=run_gate()\n    print(\"\\n=== SEED v137 REAL WAKE / ALWAYS-ON COMPANION GATE ===\")\n    print(f\"Ready: {r['ready']}\")\n    print(f\"Modules OK: {r['modules_ok']}\")\n    print(f\"Companion OK: {r['companion_ok']}\")\n    print(f\"Panel OK: {r['panel_ok']}\")\n    print(f\"Hygiene OK: {r['hygiene_ok']}\")\n    try:\n        h=r[\"details\"].get(\"hygiene\") or {}\n        print(f\"Hygiene score: {h.get('score')}/100\")\n    except Exception:\n        pass\n\nif __name__==\"__main__\":\n    show()\n"}
for path,text in FILES.items():
    Path(path).write_text(text)
    print("Wrote",path)

